entity Prob_5_58_vhdl is	port (y_out: out bit; x_in, clk, reset_b: in bit);end Prob_5_58_vhdl;architecture Behavioral of Prob_5_58_vhdl is 	constant s0: bit_vector (1 downto 0) := "00";  	constant s1: bit_vector (1 downto 0) := "01";  	constant s2: bit_vector (1 downto 0) := "10";  	constant s3: bit_vector (1 downto 0) := "11";  	signal state, next_state: bit_vector (1 downto 0);beginprocess (clk, reset_b) begin 	if (reset_b = '0') then state <= s0; 	elsif clk'event and clk = '1' then state <= next_state;end process;process (state, x_in) begin    y_out <= '0';    next_state <= s0;    case(state) is    when s0 =>		if (x_in = '0') then next_state <= s0; 					elsif (x_in = '1') then next_state = s1; end if;      when s1 =>	if (x_in = '0') then next_state <= s0; 		elsif (x_in = '1') then next_state = s2; end if;      when s2 =>	if (x_in = '1') then next_state <= s0; 		elsif (x_in = '1') then next_state <= s3;      when s3 =>	 y_out <= 1; if (x_in = '0') then next_state <= s0; 					elsif (x_in = '1') then next_state <= s3;      when others =>	next_state <= s0; y_out <= 0;     endcase  end process;end Behavioral;